parameters.jsCode:
const candidates = $input.all();
const weights = { skill: 0.40, experience: 0.30, education: 0.20, cultural: 0.10 };

candidates.forEach(c => {
  const score = (c.json.skills_match || 0) * weights.skill +
                (c.json.experience_relevance || 0) * weights.experience +
                (c.json.education_fit || 0) * weights.education +
                (c.json.cultural_indicators || 0) * weights.cultural;
  c.json.match_score = Math.round(score * 100) / 100;
});

candidates.sort((a, b) => b.json.match_score - a.json.match_score);
return candidates.slice(0, 10);

